createAssembly(raidCategory) {
    if (this.connections.length === 0) {
        console.info("No additional connections accessible.");
        return;
    }

    let countConnectionsToAdd;
    if (raidCategory === "1by1") {
        countConnectionsToAdd = 1;
    } else if (raidCategory === "xkey") {
        countConnectionsToAdd = 3;
    } else {
        console.error("Incorrect raid category.");
        return;
    }

    while (this.connections.length > 0) {
        const group = [];
        const connectionsToAdd = this.connections.slice(0, countConnectionsToAdd); // Copy the first countConnectionsToAdd elements
        for (const connection of connectionsToAdd) {
            const psk = connection.psk;
            group.push({ connection, psk, hasStash: false });
        }

        console.info(`Group ${this.groups.length + 1} formed with ${group.length} connections.`);
        this.groups.push(group);
    }
}

